@namespace sv_e2df2bcba1324d7cba9a9a40e68cffcb.Components.Pages.Board

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1 text-muted small">@Task.Assignee</p>
        <div class="d-flex justify-content-between align-items-center mb-1">
            <span class="badge @PriorityClass">@Task.Priority</span>
            <small class="text-muted">@Task.DueDate.ToString("MMM dd")</small>
        </div>
        <div class="d-flex justify-content-between">
            @if (ShowMoveLeft)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveLeft">← Move Left</button>
            }
            else
            {
                <span></span>
            }
            @if (ShowMoveRight)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveRight">Move Right →</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

@namespace sv_e2df2bcba1324d7cba9a9a40e68cffcb.Components.Pages.Board

<div class="card border-primary mt-2">
    <div class="card-body p-2">
        <div class="mb-2">
            <input type="text" class="form-control form-control-sm" placeholder="Title" @bind="Title" />
        </div>
        <div class="mb-2">
            <input type="text" class="form-control form-control-sm" placeholder="Assignee" @bind="Assignee" />
        </div>
        <div class="mb-2">
            <select class="form-select form-select-sm" @bind="Priority">
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
            </select>
        </div>
        <div class="mb-2">
            <input type="date" class="form-control form-control-sm" @bind="DueDate" />
        </div>
        <div class="d-flex gap-2">
            <button class="btn btn-primary btn-sm" @onclick="HandleSave" disabled="@Saving">
                @(Saving ? "Saving..." : "Save")
            </button>
            <button class="btn btn-secondary btn-sm" @onclick="HandleCancel" disabled="@Saving">Cancel</button>
        </div>
        @if (!string.IsNullOrEmpty(Error))
        {
            <div class="text-danger small mt-1">@Error</div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public EventCallback<AddTaskRequest> OnSave { get; set; }
    [Parameter, EditorRequired] public EventCallback OnCancel { get; set; }

    private string Title { get; set; } = "";
    private string Assignee { get; set; } = "";
    private string Priority { get; set; } = "Medium";
    private DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    private bool Saving { get; set; }
    private string? Error { get; set; }

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(Title))
        {
            Error = "Title is required.";
            return;
        }

        Error = null;
        Saving = true;
        try
        {
            await OnSave.InvokeAsync(new AddTaskRequest(Title.Trim(), Assignee.Trim(), Priority, DueDate));
        }
        catch
        {
            Error = "Failed to save task.";
        }
        finally
        {
            Saving = false;
        }
    }

    private async Task HandleCancel() => await OnCancel.InvokeAsync();

    public record AddTaskRequest(string Title, string Assignee, string Priority, DateTime DueDate);
}

@namespace sv_e2df2bcba1324d7cba9a9a40e68cffcb.Components.Pages.Board

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body" style="min-height: 200px; overflow-y: auto;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          ShowMoveLeft="ShowMoveLeft"
                          ShowMoveRight="ShowMoveRight"
                          OnMoveLeft="@(() => OnMoveLeft.InvokeAsync(task.Id))"
                          OnMoveRight="@(() => OnMoveRight.InvokeAsync(task.Id))" />
            }

            @if (ShowForm)
            {
                <AddTaskForm OnSave="HandleTaskSave" OnCancel="@(() => ShowForm = false)" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm w-100 mt-2" @onclick="@(() => ShowForm = true)">
                    + Add Task
                </button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<AddTaskForm.AddTaskRequest> OnAddTask { get; set; }

    private bool ShowForm { get; set; }

    private async Task HandleTaskSave(AddTaskForm.AddTaskRequest request)
    {
        await OnAddTask.InvokeAsync(request);
        ShowForm = false;
    }
}

@page "/board"
@namespace sv_e2df2bcba1324d7cba9a9a40e68cffcb.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Total="allTasks.Count"
                ToDo="TodoTasks.Count"
                InProgress="InProgressTasks.Count"
                Done="DoneTasks.Count"
                Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <div class="mb-3">
        <input type="text"
               class="form-control"
               placeholder="Search tasks by title..."
               @bind="searchText"
               @bind:event="oninput" />
    </div>

    <div class="row g-3">
        <KanbanColumn ColumnName="To Do"
                      Tasks="TodoTasks"
                      ShowMoveLeft="false"
                      ShowMoveRight="true"
                      OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                      OnAddTask="@(req => AddTask(req, "To Do"))" />

        <KanbanColumn ColumnName="In Progress"
                      Tasks="InProgressTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="true"
                      OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                      OnMoveRight="@(id => MoveTask(id, "Done"))"
                      OnAddTask="@(req => AddTask(req, "In Progress"))" />

        <KanbanColumn ColumnName="Done"
                      Tasks="DoneTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                      OnAddTask="@(req => AddTask(req, "Done"))" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool loading = true;
    private string? errorMessage;

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(searchText)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();

    protected override async Task OnInitializedAsync() => await LoadTasks();

    private async Task LoadTasks()
    {
        loading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            loading = false;
        }
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task AddTask(AddTaskForm.AddTaskRequest request, string status)
    {
        var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
        allTasks.Add(created with { Status = status });
    }
}

